#Requires -Version 5.0
[CmdletBinding()]
param()
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'CCHL.Bootstrap.Crypto.psm1') -Force
$owner='mcann1423';$repo='CCHL-Tech-Utilities-Installer';$assetName='cchl-tools-manager.cchl';$root=Join-Path $env:LOCALAPPDATA 'CCHL\TechUtilities';$entropy=[Text.Encoding]::UTF8.GetBytes('CCHL.TechUtilities.DistributionPassword.v1')
function Get-Sha([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
try {
 $headers=@{Accept='application/vnd.github+json';'User-Agent'='CCHL-Tech-Utilities-Installer';'X-GitHub-Api-Version'='2022-11-28'};$release=Invoke-RestMethod "https://api.github.com/repos/$owner/$repo/releases/latest" -Headers $headers;$asset=@($release.assets|Where-Object{$_.name -eq $assetName});if($asset.Count -ne 1 -or [string]$asset[0].digest -notmatch '^sha256:[0-9a-fA-F]{64}$'){throw "Latest release has no verifiable '$assetName' asset."}
 $work=Join-Path $env:TEMP ("CCHL-Install-{0}" -f [Guid]::NewGuid().ToString('N'));[void](New-Item -ItemType Directory -Path $work -Force);$encrypted=Join-Path $work $assetName;Invoke-WebRequest $asset[0].browser_download_url -OutFile $encrypted -UseBasicParsing;if((Get-Sha $encrypted) -ne $asset[0].digest.Substring(7).ToLowerInvariant()){throw 'Manager digest verification failed.'}
 $pass=Read-Host 'CCHL distribution password' -AsSecureString;$zip=Join-Path $work 'manager.zip';[IO.File]::WriteAllBytes($zip,(Unprotect-CCHLAsset ([IO.File]::ReadAllBytes($encrypted)) $pass));$stage=Join-Path $work 'manager';Expand-Archive $zip $stage -Force;if(-not(Test-Path (Join-Path $stage 'CCHL.Tools.Manager.ps1'))){throw 'Manager archive is incomplete.'}
 [void](New-Item -ItemType Directory -Path $root -Force);$target=Join-Path $root 'Manager';if(Test-Path $target){Remove-Item $target -Recurse -Force};Move-Item $stage $target;$plain=[Text.Encoding]::UTF8.GetBytes(([Runtime.InteropServices.Marshal]::PtrToStringBSTR([Runtime.InteropServices.Marshal]::SecureStringToBSTR($pass))));try{[IO.File]::WriteAllBytes((Join-Path $root 'distribution-credential.dat'),[Security.Cryptography.ProtectedData]::Protect($plain,$entropy,[Security.Cryptography.DataProtectionScope]::CurrentUser))}finally{[Array]::Clear($plain,0,$plain.Length)}
 $desktop=[Environment]::GetFolderPath('Desktop');$shell=New-Object -ComObject WScript.Shell;$shortcut=$shell.CreateShortcut((Join-Path $desktop 'CCHL Tech Utilities.lnk'));$shortcut.TargetPath='powershell.exe';$shortcut.Arguments='-NoProfile -ExecutionPolicy Bypass -File "'+(Join-Path $target 'CCHL.Tools.Manager.ps1')+'"';$shortcut.Save();Write-Host 'CCHL Tech Utilities installed.'
} catch {Write-Error $_.Exception.Message;exit 1} finally {if($pass){$pass.Dispose()};if($work){Remove-Item $work -Recurse -Force -ErrorAction SilentlyContinue}}
